import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
const source = await readFile('apps/web/public/offline-catalog.js', 'utf8');
const { catalogCopy, savePublicCatalog, readPublicCatalog } = await import(`data:text/javascript;base64,${Buffer.from(source).toString('base64')}`);
const product = { id: 'phone', lojaId: 'fixture', nome: '<script>malicious</script>', categoria: 'Celulares', preco: 999, privateField: 'never-copy' };
const saved = catalogCopy('fixture', Array.from({ length: 250 }, () => product));
assert.equal(saved.products.length, 200);
assert.equal(saved.products[0].privateField, undefined);
assert.throws(() => catalogCopy('another', [product]));
assert.throws(() => catalogCopy('fixture', [{ ...product, preco: NaN }]));
let value = null;
const storage = { getItem() { return value; }, setItem(_key, next) { value = next; }, removeItem() { value = null; } };
savePublicCatalog('fixture', [product], storage);
assert.equal(readPublicCatalog(storage).products[0].nome, product.nome);
assert.equal(readPublicCatalog(storage, Date.now() + 49 * 3600000), null);
assert.equal(value, null);
value = JSON.stringify({ ...saved, savedAt: Date.now() + 10000 }); assert.equal(readPublicCatalog(storage), null);
value = 'x'.repeat(250001); assert.equal(readPublicCatalog(storage), null);
savePublicCatalog('fixture', [product], { ...storage, setItem() { throw new Error('quota'); } }); assert.equal(value, null);
console.log('Web offline catalogue: bounded public fields, expiry, invalid rows and unavailable storage passed. DOM and actual service worker remain separate checks.');
